public final class Diag {
  static final String PID = java.lang.management.ManagementFactory.getRuntimeMXBean().getName().split("@")[0];
  static final java.util.concurrent.atomic.AtomicLong SEQ = new java.util.concurrent.atomic.AtomicLong();
  static final ThreadLocal<String> KOR = new ThreadLocal<>();
  static final java.util.concurrent.locks.ReentrantLock L = new java.util.concurrent.locks.ReentrantLock();
  static final java.io.Writer OUT;
  static { try { String f = System.getProperty("flowlens.file", "/tmp/flowlens-%pid.jsonl").replace("%pid", PID);
    OUT = new java.io.BufferedWriter(new java.io.OutputStreamWriter(new java.io.FileOutputStream(f, true), java.nio.charset.StandardCharsets.UTF_8));
  } catch (java.io.IOException e) { throw new ExceptionInInitializerError(e); } }
  public static String begin(String kor){ String k = kor != null ? kor : java.util.UUID.randomUUID().toString(); KOR.set(k); return k; }
  public static void end(){ KOR.remove(); }
  public static void ev(String ev, String klasa, String metoda, String extraJson){
    Thread t = Thread.currentThread();
    StringBuilder b = new StringBuilder(256).append("{\"ts\":").append(System.currentTimeMillis()).append(",\"ns\":").append(System.nanoTime())
      .append(",\"pid\":").append(q(PID)).append(",\"w\":").append(q(t.getName())).append(",\"tid\":").append(t.getId())
      .append(",\"kor\":").append(q(KOR.get())).append(",\"sek\":").append(SEQ.incrementAndGet())
      .append(",\"ev\":").append(q(ev)).append(",\"klasa\":").append(q(klasa)).append(",\"metoda\":").append(q(metoda));
    if (extraJson != null) b.append(',').append(extraJson);
    b.append("}\n");
    L.lock(); try { OUT.write(b.toString()); OUT.flush(); } catch (java.io.IOException ignored) {} finally { L.unlock(); }
  }
  public static String q(String s){ if (s == null) return "null"; StringBuilder b = new StringBuilder(s.length()+2).append('"');
    for (char c : s.toCharArray()) { if (c=='"'||c=='\\') b.append('\\').append(c); else if (c<0x20) b.append(String.format("\\u%04x",(int)c)); else b.append(c); }
    return b.append('"').toString(); }
}
Zmiana względem wersji badacza: pid jest zapisywany jako string (q(PID)), bo RuntimeMXBean.getName() nie musi mieć postaci pid@host i wtedy JSON byłby niepoprawny.
Wywołania: Diag.ev("in", "HTTP", "GET /orders/{id}", "\"uri\":"+Diag.q(uri)); Diag.ev("sql", null, null, "\"sql\":"+Diag.q(sql)+",\"ms\":"+ms); Diag.ev("tx", null, "begin", "\"name\":"+Diag.q(name)).

public static void premain(String a, Instrumentation inst){ new AgentBuilder.Default().ignore(nameStartsWith("net.bytebuddy.").or(nameContains("$$"))).type(nameStartsWith("com.firma.").and(not(isInterface()))).transform((b,td,cl,m,pd) -> b.visit(Advice.to(Trace.class).on(isMethod().and(not(isAbstract())).and(not(isSynthetic()))))).installOn(inst); }
class Trace { @Advice.OnMethodEnter static void in(@Advice.Origin("#t") String k, @Advice.Origin("#m") String m){ Diag.ev("in",k,m,null);} @Advice.OnMethodExit(onThrowable=Throwable.class) static void out(@Advice.Origin("#t") String k, @Advice.Origin("#m") String m, @Advice.Thrown Throwable t){ Diag.ev("out",k,m, t==null?null:"\"exc\":"+Diag.q(t.getClass().getName())); } }
Kod Advice jest wklejany do metod aplikacji, więc klasa Diag musi być widoczna z classloadera aplikacji i istnieć tylko w jednej kopii.
